-- 041_pm_weekly_reports.sql — D12 Phase 2: Weekly PM ritual.
--
-- Generated by AI (Haiku) on Saturday midnight. User signs off, optionally
-- edits, and the `feed_summary` becomes the seed for next session's
-- systemPrompt context (사료화 — feed material).

CREATE TABLE IF NOT EXISTS pm_weekly_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id INTEGER NOT NULL,
  week_start DATE NOT NULL,             -- Monday of the week
  week_end DATE NOT NULL,               -- Sunday of the week
  content TEXT NOT NULL,                -- AI-generated markdown
  feed_summary TEXT,                    -- compressed 200-400 chars for systemPrompt injection
  generated_at TIMESTAMPTZ DEFAULT NOW(),
  signed_off_at TIMESTAMPTZ,
  user_edits TEXT,                      -- user-edited markdown (overrides content for display when present)
  next_week_seed JSONB,                 -- {priorities: [...], notes: "..."}  drives Inbox seeding
  UNIQUE (user_id, week_start)
);

CREATE INDEX IF NOT EXISTS idx_pm_weekly_user_recent
  ON pm_weekly_reports(user_id, week_start DESC);

COMMENT ON TABLE pm_weekly_reports IS
  'D12 — Weekly PM report. AI writes → user signs off → feed_summary injected to next sessions.';
